-- Additions from current native entities; no historical schema rewrite or external activation.
CREATE TABLE li_notice_message (id BIGINT PRIMARY KEY, create_by VARCHAR(255), create_time DATETIME(6), delete_flag BIT(1) NOT NULL DEFAULT 0, update_by VARCHAR(255), update_time DATETIME(6), notice_node VARCHAR(50), notice_title VARCHAR(50), notice_content VARCHAR(200), notice_status VARCHAR(16), variable TEXT, scene_code VARCHAR(64), email_status VARCHAR(16), email_content VARCHAR(2000), INDEX(scene_code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE li_wechat_message (id BIGINT PRIMARY KEY, create_by VARCHAR(255), create_time DATETIME(6), delete_flag BIT(1) NOT NULL DEFAULT 0, update_by VARCHAR(255), update_time DATETIME(6), name VARCHAR(255), code VARCHAR(255), keywords TEXT, enable BIT(1) NOT NULL DEFAULT 0, order_status VARCHAR(64), first VARCHAR(1000), remark VARCHAR(1000), scene_code VARCHAR(64), INDEX(scene_code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE li_wechat_mp_message (id BIGINT PRIMARY KEY, create_by VARCHAR(255), create_time DATETIME(6), delete_flag BIT(1) NOT NULL DEFAULT 0, update_by VARCHAR(255), update_time DATETIME(6), template_id VARCHAR(255), name VARCHAR(255), code VARCHAR(255), keywords TEXT, keywords_text TEXT, enable BIT(1) NOT NULL DEFAULT 0, order_status VARCHAR(64), scene_code VARCHAR(64), INDEX(scene_code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE li_logistics (id BIGINT PRIMARY KEY, create_by VARCHAR(255), create_time DATETIME(6), delete_flag BIT(1) NOT NULL DEFAULT 0, update_by VARCHAR(255), update_time DATETIME(6), name VARCHAR(255), code VARCHAR(255), stand_by VARCHAR(255), form_items TEXT, disabled VARCHAR(16)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE li_app_version (id BIGINT PRIMARY KEY, create_time DATETIME(6), create_by VARCHAR(255), version VARCHAR(255), version_name VARCHAR(255), content TEXT, force_update BIT(1) NOT NULL DEFAULT 0, download_url VARCHAR(1000), type VARCHAR(64), version_update_date DATETIME(6)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
